import java.util.*;

class Solution {
    public int longestOnes(int[] lamps, int k) {
        int left = 0, zeros = 0, best = 0;
        for (int right = 0; right < lamps.length; right++) {
            if (lamps[right] == 0) zeros++;
            while (zeros > k) {                 // too many broken lamps: shrink from the left
                if (lamps[left] == 0) zeros--;
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

