class Solution:
    def longestOnes(self, lamps: List[int], k: int) -> int:
        l = zeros = best = 0
        for r, x in enumerate(lamps):
            if x == 0: zeros += 1
            while zeros > k:
                if lamps[l] == 0: zeros -= 1
                l += 1
            best = max(best, r - l + 1)
        return best

