function longestOnes(a, k) {
  const pre = [0]; for (const x of a) pre.push(pre[pre.length - 1] + (x === 0 ? 1 : 0));
  let best = 0;
  for (let i = 0; i < a.length; i++) {
    let lo = i, hi = a.length;
    while (lo < hi) { const m = (lo + hi + 1) >> 1; if (pre[m] - pre[i] <= k) lo = m; else hi = m - 1; }
    best = Math.max(best, lo - i);
  }
  return best;
}
